	if err := ctx.Bind(&req); err != nil {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "invalid request body"})
	}

	if req.URL == "" {
		return ctx.JSON(http.StatusBadRequest, map[string]string{"error": "url is required"})
	}

	// Create HTTP client with 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Create a new request with context for timeout handling
	reqCtx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()

	httpReq, err := http.NewRequestWithContext(reqCtx, http.MethodGet, req.URL, nil)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": fmt.Sprintf("failed to create request: %v", err)})
	}

	// Set user agent to avoid being blocked by some servers
	httpReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	resp, err := client.Do(httpReq)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": fmt.Sprintf("failed to fetch URL: %v", err)})
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": fmt.Sprintf("received non-200 status code: %d", resp.StatusCode)})
	}

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return ctx.JSON(http.StatusInternalServerError, map[string]string{"error": fmt.Sprintf("failed to read response body: %v", err)})
	}

	title, description := parseHTML(string(body))

	result := PreviewResponse{
		Title:       title,
		Description: description,
	}

	return ctx.JSON(http.StatusOK, result)
}

// parseHTML extracts title and meta description from HTML content
func parseHTML(content string) (string, string) {
	tokenizer := html.NewTokenizer(strings.NewReader(content))

	var title string
	var description string
	var inTitle bool
	var titleFound bool

	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			return title, description
		case html.StartTagToken, html.SelfClosingTagToken:
			token := tokenizer.Token()

			// Check for title tag
			if token.Data == "title" && !titleFound {
				inTitle = true
			}

			// Check for meta tags with name="description" or property="og:description"
			if token.Data == "meta" {
				var hasName, hasProperty, hasContent bool
				var nameVal, propertyVal, contentVal string

				for _, attr := range token.Attr {
					switch strings.ToLower(attr.Key) {
					case "name":
						hasName = true
						nameVal = strings.ToLower(attr.Val)
					case "property":
						hasProperty = true
						propertyVal = strings.ToLower(attr.Val)
					case "content":
						hasContent = true
						contentVal = attr.Val
					}
				}

				if hasContent {
					if hasName && nameVal == "description" && description == "" {
						description = contentVal
					} else if hasProperty && propertyVal == "og:description" && description == "" {
						description = contentVal
					}
				}
			}
		case html.TextToken:
			if inTitle && !titleFound {
				title = strings.TrimSpace(tokenizer.Token().Data)
				titleFound = true
				inTitle = false
			}
		case html.EndTagToken:
			token := tokenizer.Token()
			if token.Data == "title" {
				inTitle = false
			}
		}
	}
}

func main() {
	e := echo.New()

	e.POST("/preview", FetchURLPreview)

	// Use a shorter timeout for server startup in tests
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	go func() {
		e.Logger.Fatal(e.Start(":8080"))
	}()

	<-ctx.Done()
}
